<template><div class="app-container"><el-table v-loading="loading" :data="rows" border height="700"><el-table-column v-for="key in columns" :key="key" :prop="key" :label="labels[key]||key" min-width="120" /></el-table></div></template>
<script setup name="FutureCatalog">
import { computed, ref } from 'vue'; import { listFutureCatalog } from '@/api/future/history'
const route=useRoute(),loading=ref(false),rows=ref([]);const kind=computed(()=>route.path.includes('variety-plates')?'plates':route.path.includes('main-index')?'roles':'varieties');const columns=computed(()=>kind.value==='varieties'?['variety_code','name','exchange_code','exchange_name','margin_rate','main_contract_thscode']:kind.value==='plates'?['variety_code','variety_name','plate_level','plate_name']:['role_type','thscode','ticker','contract_name','variety_code','variety_name','exchange_code']);const labels={variety_code:'品种代码',name:'名称',exchange_code:'交易所',exchange_name:'交易所名称',margin_rate:'保证金率',main_contract_thscode:'当前主力',variety_name:'品种名称',plate_level:'板块层级',plate_name:'板块',role_type:'角色',thscode:'合约代码',ticker:'交易代码',contract_name:'合约名称'};loading.value=true;listFutureCatalog(kind.value).then(r=>rows.value=r.data||[]).finally(()=>loading.value=false)
</script>
